select o.channel, case when year(o.order_date) < 2024 then 'before_2024' when year(o.order_date) = 2024 then '2024' else 'after_2024' end as order_cohort, max(s.cost) as max_cost, max(s.shipped_date) as last_shipped_date from shipments s inner join orders o on o.id = s.order_id where s.status in ('IN_TRANSIT', 'RETURNED', 'DELIVERED') group by o.channel, case when year(o.order_date) < 2024 then 'before_2024' when year(o.order_date) = 2024 then '2024' else 'after_2024' end order by last_shipped_date, channel, order_cohort limit 20
